#include <stdint.h>
#include "stm32f411xe.h"
#include "stm32f4xx.h"

/*
 PINES DEL SIETE SEGMENTOS

   Seg A -> PB12       Seg B -> PA12       Seg C -> PC11
   Seg D -> PC12       Seg E -> PC10       Seg F -> PA11
   Seg G -> PD2        DISP1 -> PC5        DISP2 -> PC6
   DISP3 -> PC3        DISP4 -> PB7

 FOTOINTERRUPTORES
   PC2 -> SUMA  (FLANCO DE SUBIDA)
   PA0 -> RESTA (FLANCO DE BAJADA)
*/

//VARIABLES VOLÁTILES

volatile uint16_t contador = 0; //contador de 0 a 9999

/* Banderas de eventos EXTI: la ISR las activa y main las consume. */
volatile uint8_t f_suma = 0;
volatile uint8_t f_resta = 0;

volatile uint8_t f_tim2 = 0;    //evento de actualización del display



//BLINKER
static void Blinker(void);

//Funciones
void init_GPIO(void);
void init_Timers(void);
void init_EXTI(void);
void encender_segmentos(uint8_t digito);
void apagar_todo(void);
void actualizar_display(void);

int main(void)
{
    init_GPIO();
    init_Timers();
    init_EXTI();
    Blinker();


    /* Loop forever */
	while (1) {
        if (f_suma) {
            f_suma = 0;
            if (contador < 9999U) {
                contador++;
            }
        }

        if (f_resta) {
            f_resta = 0;
            if (contador > 0U) {
                contador--;
            }
        }

        if (f_tim2) {
            f_tim2 = 0;
            actualizar_display();
        }
    }

    return 0;
}


//BLINKER
void TIM1_UP_TIM10_IRQHandler(void){

if ((TIM10->SR & TIM_SR_UIF) != 0U) 
{
    TIM10->SR &= ~TIM_SR_UIF;    //limpiar la bandera de actualización
    GPIOH->ODR ^= (GPIO_ODR_OD1);//alternar el LED 
}

}


void Blinker(void){
 
    //iniciar PH1 (LED_BREADBOARD)
     RCC->AHB1ENR |= RCC_AHB1ENR_GPIOHEN;   //IO port H clock enabled
    GPIOH->MODER  &= ~GPIO_MODER_MODE1;     //LIMPIAR MODO
    GPIOH->MODER  |= GPIO_MODER_MODE1_0;    //01: General purpose output mode
    GPIOH->OTYPER &= ~GPIO_OTYPER_OT1;      //Output push-pull
    GPIOH->PUPDR  &= ~GPIO_PUPDR_PUPD1;     //No pull-up, pull-down      
    GPIOH->BSRR   &= ~GPIO_BSRR_BR1;        //No action on the corresponding ODRx bit
    //iniciar timer TIM10
    RCC->APB2ENR |= RCC_APB2ENR_TIM10EN;    //TIM10 clock enabled
    TIM10->DIER  |= TIM_DIER_UIE;           //Update interrupt enabled
    TIM10->CNT   = 0;
    TIM10->PSC   = 15999U;                  //16 MHz / 16000 = tick de 1 ms
    TIM10->ARR   = 499U;                    //500 ticks -> evento cada 500 ms
    TIM10->EGR   = TIM_EGR_UG;
    TIM10->SR    = 0;
    NVIC_EnableIRQ(TIM1_UP_TIM10_IRQn);//habilitar la línea de interrupción en el NVIC
    TIM10->CR1   |= TIM_CR1_CEN;            //Counter enabled
}   

//FUNCIONES

void init_GPIO(void){
    /*
    *GPIOA: PA11 & PA12
    *GPIOB: PB7  & PB12
    *GPIOC: PC3, PC5, PC6, PC10, PC11 & PC12
    *GPIOD: PD2
    */

    /*
    *   1. ACTIVAR SEÑAL DE RELOJ 
    */
    RCC->AHB1ENR |= (RCC_AHB1ENR_GPIOAEN | RCC_AHB1ENR_GPIOBEN | RCC_AHB1ENR_GPIOCEN | RCC_AHB1ENR_GPIODEN);

    /*
    *   2. LIMPIAR REGISTROS
    */
    //PUERTO A: PA11 (Seg F) & PA12 (Seg B)
    GPIOA->MODER    &= ~(GPIO_MODER_MODE11       | GPIO_MODER_MODE12);
    GPIOA->OTYPER   &= ~(GPIO_OTYPER_OT11        | GPIO_OTYPER_OT12);
    GPIOA->OSPEEDR  &= ~(GPIO_OSPEEDER_OSPEEDR11 | GPIO_OSPEEDER_OSPEEDR12);
    GPIOA->PUPDR    &= ~(GPIO_PUPDR_PUPD11       | GPIO_PUPDR_PUPD12);

    //PUERTO B: PB7 (DISP4) & PB12 (Seg A)
    GPIOB->MODER   &= ~(GPIO_MODER_MODER7       | GPIO_MODER_MODER12);
    GPIOB->OTYPER  &= ~(GPIO_OTYPER_OT7         | GPIO_OTYPER_OT12);
    GPIOB->OSPEEDR &= ~(GPIO_OSPEEDER_OSPEEDR7  | GPIO_OSPEEDER_OSPEEDR12);
    GPIOB->PUPDR   &= ~(GPIO_PUPDR_PUPD7        | GPIO_PUPDR_PUPD12);

    //PUERTO C: PC3 (DISP3), PC5 (DISP1), PC6 (DISP2), PC10 (Seg E), PC11 (Seg C) & PC12 (Seg D)
    GPIOC->MODER   &= ~(GPIO_MODER_MODER3  | GPIO_MODER_MODER5  |
                         GPIO_MODER_MODER6 | GPIO_MODER_MODER10 |
                         GPIO_MODER_MODER11| GPIO_MODER_MODER12);
    GPIOC->OTYPER  &= ~(GPIO_OTYPER_OT3   | GPIO_OTYPER_OT5  |
                         GPIO_OTYPER_OT6  | GPIO_OTYPER_OT10 |
                         GPIO_OTYPER_OT11 | GPIO_OTYPER_OT12);
    GPIOC->OSPEEDR &= ~(GPIO_OSPEEDER_OSPEEDR3   | GPIO_OSPEEDER_OSPEEDR5  |
                         GPIO_OSPEEDER_OSPEEDR6  | GPIO_OSPEEDER_OSPEEDR10 |
                         GPIO_OSPEEDER_OSPEEDR11 | GPIO_OSPEEDER_OSPEEDR12);
    GPIOC->PUPDR   &= ~(GPIO_PUPDR_PUPD2   | GPIO_PUPDR_PUPD5  |
                         GPIO_PUPDR_PUPD6  | GPIO_PUPDR_PUPD10 |
                         GPIO_PUPDR_PUPD11 | GPIO_PUPDR_PUPD12);

    //PUERTO D: PD2 (Seg G)
    GPIOD->MODER   &= ~(GPIO_MODER_MODER2);
    GPIOD->OTYPER  &= ~(GPIO_OTYPER_OT2);
    GPIOD->OSPEEDR &= ~(GPIO_OSPEEDER_OSPEEDR2);
    GPIOD->PUPDR   &= ~(GPIO_PUPDR_PUPD2);

    /*
    *   3. GPIOx_MODER 01: General purpose output mode
    */
    GPIOA->MODER |= (GPIO_MODER_MODER11_0 | GPIO_MODER_MODER12_0);
    GPIOB->MODER |= (GPIO_MODER_MODER7_0  | GPIO_MODER_MODER12_0);
    GPIOC->MODER |= (GPIO_MODER_MODER3_0  | GPIO_MODER_MODER5_0  |
                     GPIO_MODER_MODER6_0  | GPIO_MODER_MODER10_0 |
                     GPIO_MODER_MODER11_0 | GPIO_MODER_MODER12_0);
    GPIOD->MODER |= (GPIO_MODER_MODER2_0);

    //GPIOx_OTYPER 0: Output push-pull (reset state)

    /*
    *   4. GPIOx_OSPEEDR 01: Medium speed
    */
    GPIOA->OSPEEDR |= (GPIO_OSPEEDER_OSPEEDR11_0 | GPIO_OSPEEDER_OSPEEDR12_0);
    GPIOB->OSPEEDR |= (GPIO_OSPEEDER_OSPEEDR7_0  | GPIO_OSPEEDER_OSPEEDR12_0);
    GPIOC->OSPEEDR |= (GPIO_OSPEEDER_OSPEEDR3_0  | GPIO_OSPEEDER_OSPEEDR5_0  |
                       GPIO_OSPEEDER_OSPEEDR6_0  | GPIO_OSPEEDER_OSPEEDR10_0 |
                       GPIO_OSPEEDER_OSPEEDR11_0 | GPIO_OSPEEDER_OSPEEDR12_0);
    GPIOD->OSPEEDR |= (GPIO_OSPEEDER_OSPEEDR2_0);

    //GPIOx_PUPDR 00: No pull-up, pull-down

    /*
    *   5. GPIOx_ODR
    */
    GPIOA->ODR |= (GPIO_ODR_OD11 | GPIO_ODR_OD12);
    GPIOB->ODR |= (GPIO_ODR_OD7  | GPIO_ODR_OD12);
    GPIOC->ODR |= (GPIO_ODR_OD3  | GPIO_ODR_OD5  | GPIO_ODR_OD6  |
                   GPIO_ODR_OD10 | GPIO_ODR_OD11 | GPIO_ODR_OD12);
    GPIOD->ODR |= (GPIO_ODR_OD2);

    /*
    *   6.GPIOx_BSRR 1: Sets the corresponding ODRx bit
    */
    GPIOA->BSRR = (GPIO_BSRR_BS11 | GPIO_BSRR_BS12);
    GPIOB->BSRR = (GPIO_BSRR_BS12 | GPIO_BSRR_BS7);
    GPIOC->BSRR = (GPIO_BSRR_BS3  | GPIO_BSRR_BS5  |
                   GPIO_BSRR_BS6  | GPIO_BSRR_BS10 |
                   GPIO_BSRR_BS11 | GPIO_BSRR_BS12);
    GPIOD->BSRR = (GPIO_BSRR_BS2);


}

void init_Timers(void){
    RCC->APB1ENR |= RCC_APB1ENR_TIM2EN;

    TIM2->CR1 = 0;
    TIM2->PSC = 16000 - 1;
    TIM2->ARR = 4 - 1;
    TIM2->CNT = 0;
    TIM2->CR1 |= TIM_CR1_ARPE;
    TIM2->EGR = TIM_EGR_UG;         // cargar prescaler y ARR
    TIM2->SR = 0;                   // limpiar UIF generado por UG
    TIM2->DIER |= TIM_DIER_UIE;

    __NVIC_EnableIRQ(TIM2_IRQn);
    TIM2->CR1 |= TIM_CR1_CEN;
}

void init_EXTI(void){
    RCC->APB2ENR |= RCC_APB2ENR_SYSCFGEN;

    //CONFIGURAR PA0 & PC2 COMO ENTRADAS
    GPIOA->MODER &= ~GPIO_MODER_MODE0;  //00: Input (reset state)
    GPIOC->MODER &= ~GPIO_MODER_MODE2;  //00: Input (reset state)
    GPIOA->PUPDR &= ~GPIO_PUPDR_PUPD0;  //00: No pull-up, pull-down
    GPIOC->PUPDR &= ~GPIO_PUPDR_PUPD2;  //00: No pull-up, pull-down

    //MAPERA PA0 -> EXTI0 & PC2 -> EXTI2
    SYSCFG->EXTICR[0] &= ~(SYSCFG_EXTICR1_EXTI0 | SYSCFG_EXTICR1_EXTI2);
    SYSCFG->EXTICR[0] |=  (SYSCFG_EXTICR1_EXTI0_PA | SYSCFG_EXTICR1_EXTI2_PC);

    //PC2 (SUMA): flanco de subida
    EXTI->RTSR |= EXTI_RTSR_TR2;    //1: Rising trigger enabled (for Event and Interrupt) for input line
    EXTI->FTSR &= ~EXTI_FTSR_TR2;   //0: Falling trigger disabled (for Event and Interrupt) for input line

    //PA0 (RESTA): flanco de bajada
    EXTI->FTSR |= EXTI_FTSR_TR0;    //1: Falling trigger enabled (for Event and Interrupt) for input line.
    EXTI->RTSR &= ~EXTI_RTSR_TR0;   //0: Rising trigger disabled (for Event and Interrupt) for input line

    EXTI->PR = EXTI_PR_PR0 | EXTI_PR_PR2; // descartar pendientes anteriores al habilitar
    //Interrupt mask register (EXTI_IMR)
    EXTI->IMR |= (EXTI_IMR_MR0 | EXTI_IMR_MR2);

    __NVIC_EnableIRQ(EXTI0_IRQn);
    __NVIC_EnableIRQ(EXTI2_IRQn);
}   

// Mapa de segmentos, ánodo común: nivel bajo enciende el segmento.
// A=PB12, B=PA12, C=PC11, D=PC12, E=PC10, F=PA11, G=PD2.
void encender_segmentos(uint8_t digito) {
    static const uint8_t patrones[10] = {
        0x3FU, // 0: A B C D E F
        0x06U, // 1: B C
        0x5BU, // 2: A B D E G
        0x4FU, // 3: A B C D G
        0x66U, // 4: B C F G
        0x6DU, // 5: A C D F G
        0x7DU, // 6: A C D E F G
        0x07U, // 7: A B C
        0x7FU, // 8: A B C D E F G
        0x6FU  // 9: A B C D F G
    };
    uint8_t p;
    uint32_t bits_a = 0;
    uint32_t bits_b = 0;
    uint32_t bits_c = 0;
    uint32_t bits_d = 0;

    if (digito > 9U) {
        return;
    }
    p = patrones[digito];

    if (p & (1U << 0)) bits_b |= GPIO_ODR_OD12; // A -> PB12
    if (p & (1U << 1)) bits_a |= GPIO_ODR_OD12; // B -> PA12
    if (p & (1U << 2)) bits_c |= GPIO_ODR_OD11; // C -> PC11
    if (p & (1U << 3)) bits_c |= GPIO_ODR_OD12; // D -> PC12
    if (p & (1U << 4)) bits_c |= GPIO_ODR_OD10; // E -> PC10
    if (p & (1U << 5)) bits_a |= GPIO_ODR_OD11; // F -> PA11
    if (p & (1U << 6)) bits_d |= GPIO_ODR_OD2;  // G -> PD2

    GPIOA->BSRR = bits_a << 16;
    GPIOB->BSRR = bits_b << 16;
    GPIOC->BSRR = bits_c << 16;
    GPIOD->BSRR = bits_d << 16;
}

void apagar_todo(void) {
    /* PNP activos en bajo: apagar los cuatro dígitos. */
    GPIOB->BSRR = GPIO_BSRR_BS7;                 // DISP4
    GPIOC->BSRR = GPIO_BSRR_BS5 | GPIO_BSRR_BS6 | GPIO_BSRR_BS3; // DISP1-3

    /* Ánodo común: poner los cátodos en alto apaga todos los segmentos. */
    GPIOA->BSRR = GPIO_BSRR_BS11 | GPIO_BSRR_BS12;
    GPIOB->BSRR = GPIO_BSRR_BS12;
    GPIOC->BSRR = GPIO_BSRR_BS10 | GPIO_BSRR_BS11 | GPIO_BSRR_BS12;
    GPIOD->BSRR = GPIO_BSRR_BS2;
}

void actualizar_display(void) {
    static uint8_t digito_actual = 0;
    uint16_t valor = contador;
    uint8_t unidades = (uint8_t)(valor % 10U);
    uint8_t decenas = (uint8_t)((valor / 10U) % 10U);
    uint8_t centenas = (uint8_t)((valor / 100U) % 10U);
    uint8_t millares = (uint8_t)(valor / 1000U);
    uint8_t valor_digito;

    apagar_todo();

    switch (digito_actual) {
        case 0:
            valor_digito = unidades;
            break;
        case 1:
            valor_digito = decenas;
            break;
        case 2:
            valor_digito = centenas;
            break;
        default:
            valor_digito = millares;
            break;
    }

    encender_segmentos(valor_digito);

    /* PNP: base baja activa el dígito seleccionado. */
    switch (digito_actual) {
        case 0: GPIOB->BSRR = GPIO_BSRR_BR7; break; // DISP4, unidades
        case 1: GPIOC->BSRR = GPIO_BSRR_BR3; break; // DISP3, decenas
        case 2: GPIOC->BSRR = GPIO_BSRR_BR6; break; // DISP2, centenas
        default: GPIOC->BSRR = GPIO_BSRR_BR5; break; // DISP1, millares
    }

    digito_actual = (uint8_t)((digito_actual + 1U) & 0x03U);
}

void EXTI0_IRQHandler(void) {
    if (EXTI->PR & EXTI_PR_PR0) {
        EXTI->PR = EXTI_PR_PR0; // PA0, pulso de resta por flanco descendente
        f_resta = 1;
    }
}

void EXTI2_IRQHandler(void) {
    if (EXTI->PR & EXTI_PR_PR2) {
        EXTI->PR = EXTI_PR_PR2; // PC2, pulso de suma por flanco ascendente
        f_suma = 1;
    }
}

void TIM2_IRQHandler(void) {
    if (TIM2->SR & TIM_SR_UIF) {
        TIM2->SR &= ~TIM_SR_UIF;
        f_tim2 = 1;
    }
}
